//! Cross-language parity against golden files generated by the Apple
//! `TabToolKit` implementation.
//!
//! Every file in `testdata/golden` is loaded, its inputs are rebuilt, the Rust
//! implementation runs on them, and the results are compared deeply. The
//! Swift implementation is the binding contract, so these tests are the
//! authority for collation, encoding, clipboard and export behavior.
#![cfg(target_os = "macos")]

use std::path::PathBuf;

use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use serde_json::{Value, json};
use tabtool_core::{
    CsvConfiguration, CsvError, CsvFormatDetector, CsvParser, CsvTable, CsvWriteIssue, CsvWriter,
    Encoding, ExportFormat, ExportInput, FilterCriterion, FilterOperator, Locale, RowFilter,
    SortDirection, export_data, export_preflight_issue, make_tsv, parse_tsv, row_order_sorted_by,
};

/// The `Reading/` plus `Heuristic/` fixture count.
const FIXTURE_COUNT: usize = 34;
/// One case per operator plus disabled, empty value, unknown column, invalid
/// regex, AND, the six canonical-equivalence cases and three non-ASCII digit
/// cases.
const FILTER_CASE_COUNT: usize = 27;
const CLIPBOARD_PARSE_COUNT: usize = 9;
const CLIPBOARD_MAKE_COUNT: usize = 5;
const EXPORT_CASE_COUNT: usize = 13;
/// Cells in the curated sort corpus.
const SORT_CORPUS_SIZE: usize = 43;
/// Number of ISO-2022-JP single bytes where Foundation is lenient and
/// `encoding_rs` rejects: SO, SI, ESC and all bytes >= 0x80.
const ISO_2022_JP_DECODE_EXCLUSIONS: usize = 131;

/// Directory holding the Swift-generated golden files.
fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/golden")
}

/// Path of the tracked Foundation/ICU4X sort divergences.
fn known_divergences_path() -> PathBuf {
    golden_dir().join("known_divergences.json")
}

/// Every golden file, sorted by locale for deterministic failures.
fn golden_files() -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = std::fs::read_dir(golden_dir())
        .expect("golden directory exists")
        .map(|entry| entry.expect("directory entry is readable").path())
        .filter(|path| {
            path.extension()
                .is_some_and(|extension| extension == "json")
                && path
                    .file_name()
                    .is_some_and(|name| name != "known_divergences.json")
        })
        .collect();
    files.sort();
    assert!(!files.is_empty(), "no golden files found");
    files
}

fn text(value: &Value) -> &str {
    value.as_str().expect("golden field is a string")
}

fn flag(value: &Value) -> bool {
    value.as_bool().expect("golden field is a boolean")
}

fn number(value: &Value) -> u64 {
    value.as_u64().expect("golden field is an unsigned integer")
}

/// The encoding named by its display-order identifier.
fn encoding(value: &Value) -> Encoding {
    let id = u16::try_from(number(value)).expect("encoding id fits u16");
    Encoding::from_id(id).unwrap_or_else(|| panic!("unknown encoding id {id}"))
}

/// Rows from a JSON array of arrays.
fn rows(value: &Value) -> Vec<Vec<String>> {
    value
        .as_array()
        .expect("golden rows are an array")
        .iter()
        .map(|row| {
            row.as_array()
                .expect("golden row is an array")
                .iter()
                .map(|cell| text(cell).to_owned())
                .collect()
        })
        .collect()
}

/// One flat array of strings.
fn cells(value: &Value) -> Vec<String> {
    value
        .as_array()
        .expect("golden cells are an array")
        .iter()
        .map(|cell| text(cell).to_owned())
        .collect()
}

/// One flat array of row indexes.
fn indexes(value: &Value) -> Vec<usize> {
    value
        .as_array()
        .expect("golden indexes are an array")
        .iter()
        .map(|index| usize::try_from(number(index)).expect("index fits usize"))
        .collect()
}

/// A configuration in the golden JSON shape.
fn configuration(value: &Value) -> CsvConfiguration {
    CsvConfiguration {
        encoding: encoding(&value["encoding"]),
        column_separator: text(&value["separator"]).to_owned(),
        quote_character: text(&value["quote"]).to_owned(),
        escape_character: text(&value["escape"]).to_owned(),
        decimal_mark: text(&value["decimalMark"]).to_owned(),
        first_row_as_header: flag(&value["header"]),
    }
}

/// The golden JSON shape of a configuration.
fn configuration_json(configuration: &CsvConfiguration) -> Value {
    json!({
        "encoding": configuration.encoding.id(),
        "separator": configuration.column_separator,
        "quote": configuration.quote_character,
        "escape": configuration.escape_character,
        "decimalMark": configuration.decimal_mark,
        "header": configuration.first_row_as_header,
    })
}

/// The locale stored in the golden file.
fn locale(document: &Value) -> Locale {
    text(&document["locale"])
        .replace('_', "-")
        .parse()
        .expect("golden locale is valid")
}

fn sort_direction(value: &Value) -> SortDirection {
    match text(value) {
        "ascending" => SortDirection::Ascending,
        "descending" => SortDirection::Descending,
        other => panic!("unknown sort direction {other:?}"),
    }
}

fn filter_operator(name: &str) -> FilterOperator {
    match name {
        "equals" => FilterOperator::Equals,
        "notEquals" => FilterOperator::NotEquals,
        "contains" => FilterOperator::Contains,
        "notContains" => FilterOperator::NotContains,
        "beginsWith" => FilterOperator::BeginsWith,
        "endsWith" => FilterOperator::EndsWith,
        "greaterThan" => FilterOperator::GreaterThan,
        "lessThan" => FilterOperator::LessThan,
        "greaterOrEqual" => FilterOperator::GreaterOrEqual,
        "lessOrEqual" => FilterOperator::LessOrEqual,
        "isEmpty" => FilterOperator::IsEmpty,
        "isNotEmpty" => FilterOperator::IsNotEmpty,
        "matchesRegex" => FilterOperator::MatchesRegex,
        other => panic!("unknown filter operator {other:?}"),
    }
}

fn issue_name(issue: CsvWriteIssue) -> &'static str {
    match issue {
        CsvWriteIssue::UnencodableText => "unencodableText",
        CsvWriteIssue::AmbiguousOutput => "ambiguousOutput",
    }
}

/// Rebuilds every fixture input and compares detection, rows and writes.
fn check_fixtures(locale_name: &str, document: &Value) {
    let encodings = document["encodings"]
        .as_array()
        .expect("encodings are an array");
    assert_eq!(
        encodings.iter().map(text).collect::<Vec<_>>(),
        Encoding::ALL
            .iter()
            .map(|encoding| encoding.display_name())
            .collect::<Vec<_>>(),
        "{locale_name}: encoding list"
    );

    let fixtures = document["fixtures"]
        .as_array()
        .expect("fixtures are an array");
    assert_eq!(
        fixtures.len(),
        FIXTURE_COUNT,
        "{locale_name}: fixture count"
    );
    let mut expected_names: Vec<&str> = tabtool_testdata::fixture_names()
        .iter()
        .copied()
        .filter(|name| name.starts_with("Reading/") || name.starts_with("Heuristic/"))
        .collect();
    expected_names.sort_unstable();
    let mut actual_names: Vec<&str> = fixtures
        .iter()
        .map(|fixture| text(&fixture["name"]))
        .collect();
    actual_names.sort_unstable();
    assert_eq!(actual_names, expected_names, "{locale_name}: fixture list");

    for fixture in fixtures {
        let name = text(&fixture["name"]);
        let data = tabtool_testdata::fixture(name);
        let context = format!("{locale_name}: fixture {name}");

        let detected = CsvFormatDetector::new(&data, false).detect();
        assert_eq!(
            configuration_json(&detected),
            fixture["detected"],
            "{context}: detection"
        );

        let mut parser = CsvParser::from_bytes(&data, &detected)
            .unwrap_or_else(|error| panic!("{context}: parser setup failed: {error:?}"));
        assert_eq!(
            parser.had_utf8_bom(),
            flag(&fixture["hadUTF8BOM"]),
            "{context}: hadUTF8BOM"
        );
        let parsed = parser
            .read_all()
            .unwrap_or_else(|error| panic!("{context}: parse failed: {error:?}"));
        assert_eq!(json!(parsed), fixture["rows"], "{context}: rows");

        let table = CsvTable::from_rows(parsed, None, 1);
        let include_utf8_bom = flag(&fixture["hadUTF8BOM"]);
        for write in fixture["writes"].as_array().expect("writes are an array") {
            let write_encoding = encoding(&write["encoding"]);
            let write_context = format!("{context}: write {write_encoding:?}");
            let write_configuration = configuration(&write["configuration"]);
            assert_eq!(
                write_configuration.encoding, write_encoding,
                "{write_context}: encoding mismatch in configuration"
            );

            let writer = CsvWriter {
                table: &table,
                header: None,
                configuration: &write_configuration,
                include_utf8_bom,
                allow_ambiguous_output: false,
            };
            let decoded = write_encoding.decode(&data);
            match write.get("skip").and_then(Value::as_str) {
                Some("cannotDecodeData") => assert!(
                    decoded.is_err(),
                    "{write_context}: Rust accepted bytes Foundation rejected"
                ),
                Some("unencodableText") => {
                    assert!(
                        decoded.is_ok(),
                        "{write_context}: decode failed before the write"
                    );
                    assert_eq!(
                        writer.data(),
                        Err(CsvError::UnencodableText),
                        "{write_context}: expected unencodable text"
                    );
                }
                Some("ambiguousOutput") => {
                    assert!(
                        decoded.is_ok(),
                        "{write_context}: decode failed before the write"
                    );
                    assert_eq!(
                        writer.data(),
                        Err(CsvError::AmbiguousOutput),
                        "{write_context}: expected ambiguous output"
                    );
                }
                Some(reason) => panic!("{write_context}: unknown skip reason {reason:?}"),
                None => {
                    assert!(
                        decoded.is_ok(),
                        "{write_context}: Rust rejected bytes Foundation accepted"
                    );
                    let bytes = writer
                        .data()
                        .unwrap_or_else(|error| panic!("{write_context}: write failed: {error:?}"));
                    assert_eq!(
                        STANDARD.encode(bytes),
                        text(&write["base64"]),
                        "{write_context}: bytes"
                    );
                }
            }
        }
    }
}

/// Rebuilds every encoding oracle entry and compares Foundation with Rust.
///
/// The oracle decodes all 256 single bytes for each encoding and encodes a
/// fixed sample set. ISO-2022-JP is stateful and Foundation passes incomplete
/// escape sequences and 8-bit bytes through where `encoding_rs` rejects them;
/// those 131 exact cases are asserted to be the only divergence.
fn check_encoding_oracle(locale_name: &str, document: &Value) {
    let oracle = &document["encodingOracle"];
    let samples = cells(&oracle["samples"]);
    let entries = oracle["encodings"]
        .as_array()
        .expect("encoding oracle entries are an array");
    assert_eq!(
        entries.len(),
        Encoding::ALL.len(),
        "{locale_name}: oracle encoding count"
    );

    for (index, entry) in entries.iter().enumerate() {
        let encoding = encoding(&entry["encoding"]);
        assert_eq!(
            usize::from(encoding.id()),
            index,
            "{locale_name}: oracle encoding order"
        );
        let context = format!("{locale_name}: {encoding:?}");

        let decode = entry["decode"]
            .as_array()
            .expect("oracle decode table is an array");
        assert_eq!(decode.len(), 256, "{context}: decode table size");
        let mut lenient = 0;
        for (value, expected) in decode.iter().enumerate() {
            let byte = u8::try_from(value).expect("byte fits u8");
            let bytes = [byte];
            let decoded = encoding.decode(&bytes);
            if encoding == Encoding::Iso2022Jp && is_iso2022jp_lenient_byte(byte) {
                lenient += 1;
                assert_eq!(
                    expected,
                    &Value::String(char::from(byte).to_string()),
                    "{context}: byte {byte:#04x} Foundation pass-through changed"
                );
                assert_eq!(
                    decoded,
                    Err(CsvError::CannotDecodeData),
                    "{context}: byte {byte:#04x} Rust leniency changed"
                );
                continue;
            }

            match expected {
                Value::Null => assert_eq!(
                    decoded,
                    Err(CsvError::CannotDecodeData),
                    "{context}: byte {byte:#04x} should be rejected"
                ),
                Value::String(text) => assert_eq!(
                    decoded.as_deref(),
                    Ok(text.as_str()),
                    "{context}: byte {byte:#04x}"
                ),
                other => panic!("{context}: unexpected decode entry {other:?}"),
            }
        }
        if encoding == Encoding::Iso2022Jp {
            assert_eq!(
                lenient, ISO_2022_JP_DECODE_EXCLUSIONS,
                "{context}: ISO-2022-JP decoder leniency set changed"
            );
        }

        let encode = entry["encode"]
            .as_array()
            .expect("oracle encode table is an array");
        assert_eq!(encode.len(), samples.len(), "{context}: encode table size");
        for (sample, expected) in samples.iter().zip(encode) {
            match expected {
                Value::Null => assert_eq!(
                    encoding.encode(sample),
                    Err(CsvError::UnencodableText),
                    "{context}: {sample:?} should be unencodable"
                ),
                Value::String(encoded) => {
                    let bytes = STANDARD
                        .decode(encoded)
                        .expect("oracle encode bytes are base64");
                    assert_eq!(encoding.encode(sample), Ok(bytes), "{context}: {sample:?}");
                }
                other => panic!("{context}: unexpected encode entry {other:?}"),
            }
        }
    }

    let decode_cases = document["encodingDecodeCases"]
        .as_array()
        .expect("encoding decode cases are an array");
    assert!(
        !decode_cases.is_empty(),
        "{locale_name}: encoding decode cases"
    );
    for case in decode_cases {
        let name = text(&case["name"]);
        let encoding = encoding(&case["encoding"]);
        let bytes = STANDARD
            .decode(text(&case["base64"]))
            .expect("decode case bytes are base64");
        let context = format!("{locale_name}: decode case {name}");
        match case.get("text") {
            Some(Value::String(expected)) => assert_eq!(
                encoding.decode(&bytes).unwrap().as_ref(),
                expected,
                "{context}"
            ),
            _ => assert_eq!(
                encoding.decode(&bytes),
                Err(CsvError::CannotDecodeData),
                "{context}"
            ),
        }
    }
}

/// Whether Foundation's ISO-2022-JP decoder passes this byte through while
/// `encoding_rs` rejects it.
fn is_iso2022jp_lenient_byte(byte: u8) -> bool {
    matches!(byte, 0x0E | 0x0F | 0x1B) || byte >= 0x80
}

/// Rebuilds every sort case and compares the row order.
fn check_sort(locale_name: &str, document: &Value, locale: &Locale) {
    let cases = document["sort"]
        .as_array()
        .expect("sort cases are an array");
    assert_eq!(cases.len(), 4, "{locale_name}: sort case count");
    for case in cases {
        let name = text(&case["name"]);
        let values = cells(&case["cells"]);
        assert_eq!(
            values.len(),
            SORT_CORPUS_SIZE,
            "{locale_name}: sort corpus size"
        );
        let table = CsvTable::from_rows(
            values.iter().map(|cell| vec![cell.clone()]).collect(),
            None,
            1,
        );
        let order = row_order_sorted_by(
            &table,
            0,
            sort_direction(&case["direction"]),
            text(&case["decimalMark"]),
            locale,
        );
        let expected: Vec<usize> = case["order"]
            .as_array()
            .expect("order is an array")
            .iter()
            .map(|index| usize::try_from(number(index)).expect("order index fits usize"))
            .collect();
        assert_eq!(order, expected, "{locale_name}: sort {name}");
    }
}

/// Rebuilds every filter case and compares the matching rows.
fn check_filters(locale_name: &str, document: &Value) {
    let cases = document["filters"]
        .as_array()
        .expect("filter cases are an array");
    assert_eq!(
        cases.len(),
        FILTER_CASE_COUNT,
        "{locale_name}: filter count"
    );
    for case in cases {
        let name = text(&case["name"]);
        let table = CsvTable::from_rows(rows(&case["rows"]), None, 3);
        let criteria: Vec<FilterCriterion> = case["criteria"]
            .as_array()
            .expect("criteria are an array")
            .iter()
            .map(|criterion| {
                let column = criterion["column"]
                    .as_i64()
                    .expect("criterion column is an integer");
                let column_id = usize::try_from(column)
                    .ok()
                    .and_then(|column| table.columns.get(column))
                    .map(|column| column.id);
                FilterCriterion {
                    id: 1,
                    is_enabled: flag(&criterion["enabled"]),
                    column_id,
                    op: filter_operator(text(&criterion["op"])),
                    value: text(&criterion["value"]).to_owned(),
                }
            })
            .collect();
        let matching = RowFilter { criteria }.matching_rows(&table, ".");
        let expected: Vec<usize> = case["matching"]
            .as_array()
            .expect("matching is an array")
            .iter()
            .map(|index| usize::try_from(number(index)).expect("matching index fits usize"))
            .collect();
        assert_eq!(matching, expected, "{locale_name}: filter {name}");
    }
}

/// Rebuilds the clipboard parse and make cases.
fn check_clipboard(locale_name: &str, document: &Value) {
    let parse_cases = document["clipboard"]["parse"]
        .as_array()
        .expect("clipboard parse cases are an array");
    assert_eq!(
        parse_cases.len(),
        CLIPBOARD_PARSE_COUNT,
        "{locale_name}: clipboard parse count"
    );
    for case in parse_cases {
        let input = text(&case["input"]);
        assert_eq!(
            json!(parse_tsv(input)),
            case["rows"],
            "{locale_name}: clipboard parse {input:?}"
        );
    }

    let make_cases = document["clipboard"]["make"]
        .as_array()
        .expect("clipboard make cases are an array");
    assert_eq!(
        make_cases.len(),
        CLIPBOARD_MAKE_COUNT,
        "{locale_name}: clipboard make count"
    );
    for case in make_cases {
        let output = make_tsv(
            &rows(&case["rows"]),
            text(&case["decimalMark"]),
            text(&case["separator"]),
        );
        assert_eq!(
            output,
            text(&case["output"]),
            "{locale_name}: clipboard make {:?}",
            case["rows"]
        );
    }
}

/// Rebuilds every export case, including its preflight issue and bytes.
fn check_export(locale_name: &str, document: &Value) {
    let cases = document["export"]
        .as_array()
        .expect("export cases are an array");
    assert_eq!(
        cases.len(),
        EXPORT_CASE_COUNT,
        "{locale_name}: export count"
    );
    for case in cases {
        let name = text(&case["name"]);
        let headers = match &case["headers"] {
            Value::Null => None,
            header_values => Some(cells(header_values)),
        };
        let table = CsvTable::from_rows(rows(&case["rows"]), headers, 1);
        let document_configuration = configuration(&case["document"]);
        let export_configuration = configuration(&case["export"]);
        let input = ExportInput {
            table: &table,
            format: ExportFormat::Csv,
            document_configuration: &document_configuration,
            export_configuration: &export_configuration,
        };
        let context = format!("{locale_name}: export {name}");

        match export_preflight_issue(&input) {
            None => {
                assert!(
                    case["preflight"].is_null(),
                    "{context}: unexpected preflight {:?}",
                    case["preflight"]
                );
                let bytes = export_data(&input, false)
                    .unwrap_or_else(|error| panic!("{context}: export failed: {error:?}"));
                assert_eq!(
                    STANDARD.encode(bytes),
                    text(&case["base64"]),
                    "{context}: bytes"
                );
            }
            Some(issue) => {
                assert_eq!(
                    issue_name(issue),
                    text(&case["preflight"]),
                    "{context}: preflight"
                );
                assert!(case["base64"].is_null(), "{context}: bytes on failure");
            }
        }
    }
}

/// Asserts that every tracked Foundation/ICU4X divergence is still real and
/// that the Rust order has not changed. The Foundation order comes from the
/// locale's Swift-generated golden, never from the tracked file.
fn check_known_divergences() {
    let contents = std::fs::read_to_string(known_divergences_path())
        .expect("known divergences file is readable");
    let document: Value =
        serde_json::from_str(&contents).expect("known divergences file is valid JSON");
    let entries = document.as_array().expect("known divergences are an array");
    assert!(!entries.is_empty(), "known divergences are tracked");

    for entry in entries {
        let locale_id = text(&entry["locale"]);
        let locale: Locale = locale_id
            .replace('_', "-")
            .parse()
            .expect("divergence locale is valid");
        let values = cells(&entry["cells"]);
        let context = format!("known divergence {locale_id}: {:?}", entry["cells"]);

        let golden_path = golden_dir().join(format!("{locale_id}.json"));
        let golden_contents = std::fs::read_to_string(&golden_path).unwrap_or_else(|error| {
            panic!("{context}: cannot read {}: {error}", golden_path.display())
        });
        let golden: Value =
            serde_json::from_str(&golden_contents).expect("divergence golden file is valid JSON");
        let divergences = golden["sortDivergences"]
            .as_array()
            .expect("sort divergences are an array");
        let divergence = divergences
            .iter()
            .find(|divergence| cells(&divergence["cells"]) == values)
            .unwrap_or_else(|| panic!("{context}: no Foundation order in the golden"));

        let table = CsvTable::from_rows(
            values.iter().map(|cell| vec![cell.clone()]).collect(),
            None,
            1,
        );
        let order = row_order_sorted_by(&table, 0, SortDirection::Ascending, ".", &locale);
        let foundation = indexes(&divergence["foundationOrder"]);
        let rust = indexes(&entry["rustOrder"]);

        assert_ne!(
            foundation, rust,
            "{context}: no longer diverges; remove it from the tracked file"
        );
        assert_eq!(
            order, rust,
            "{context}: Rust order changed; re-evaluate the divergence"
        );
        let expected: Vec<usize> = (0..values.len()).collect();
        for (name, order) in [("foundationOrder", &foundation), ("rustOrder", &rust)] {
            let mut sorted = order.clone();
            sorted.sort_unstable();
            assert_eq!(sorted, expected, "{context}: {name} is a permutation");
        }
        assert!(!text(&entry["reason"]).is_empty(), "{context}: reason");
    }
}

#[test]
fn rust_matches_every_swift_golden() {
    let mut locales = Vec::new();
    for path in golden_files() {
        let contents = std::fs::read_to_string(&path).expect("golden file is readable");
        let document: Value = serde_json::from_str(&contents).expect("golden file is valid JSON");
        let locale_name = text(&document["locale"]);
        let locale = locale(&document);
        locales.push(locale_name.to_owned());

        check_fixtures(locale_name, &document);
        check_sort(locale_name, &document, &locale);
        check_filters(locale_name, &document);
        check_clipboard(locale_name, &document);
        check_export(locale_name, &document);
        check_encoding_oracle(locale_name, &document);
    }
    locales.sort_unstable();
    assert_eq!(
        locales,
        ["de_DE", "en_US", "fr_FR", "ja_JP", "ko_KR", "zh_CN"],
        "golden locale set"
    );
}

#[test]
fn rust_matches_known_divergences() {
    check_known_divergences();
}
